'use strict';
const assert=require('assert');
const fs=require('fs');
const path=require('path');
const root=path.join(__dirname,'..');
const index=fs.readFileSync(path.join(root,'index.html'),'utf8');
const app=fs.readFileSync(path.join(root,'app.js'),'utf8');
const css=fs.readFileSync(path.join(root,'schedule-foundation.css'),'utf8');
const sw=fs.readFileSync(path.join(root,'service-worker.js'),'utf8');
assert(index.includes('56.0.5-schedule-card-format1'),'HTML must use v55.4.6 cache token');
assert(sw.includes('tuinbooks-shell-v56-0-5-schedule-card-format1'),'Service worker must use v55.4.6 cache');
assert(index.includes('<h1>Work to schedule</h1>'),'Catch-up page must be renamed Work to schedule');
assert(index.includes('Accepted quotes'),'Work to schedule overview must include accepted quotes');
assert(app.includes("queueSource:'accepted-quote'"),'Accepted quotes must enter the scheduling queue');
assert(app.includes('startQueueItemDragV5546'),'Queue cards must be independently draggable');
assert(app.includes('Drag this header to move the window'),'Queue window must have an explicit move handle');
assert(!index.includes('>Find space<'),'No visible Find space control may remain in the deploy');
assert(app.includes("return job?.quoteId")||app.includes("job?.quoteId||"),'Work markers must recognise quoted work as once-off');
assert(app.includes('schedule-work-marker'),'Schedule cards must include R/O markers');
assert(app.includes('Outstanding')&&app.includes('Accepted ${fmtDate(date)}'),'Queue cards must show outstanding and accepted age');
assert(app.includes("$('weekReviewPanel')?.classList.add('hidden')"),'Legacy week review block must be removed from calendar flow');
assert(css.includes('.schedule-work-queue-v5546'),'Movable work queue must have dedicated styling');
assert(css.includes('.week-review-dialog-v5546'),'Detailed week review must use a compact dialog');
console.log('v55.4.6 work-to-schedule tests passed');
